import{_ as t,c as e,o,a7 as d}from"./chunks/framework.DNE_2Uup.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"basic/htmlcssjs/html/常见的标签元素.md","filePath":"basic/htmlcssjs/html/常见的标签元素.md","lastUpdated":1745417180000}'),i={name:"basic/htmlcssjs/html/常见的标签元素.md"};function a(c,l,r,h,s,n){return o(),e("div",null,l[0]||(l[0]=[d('<h3 id="html-中常见的标签元素及其分类" tabindex="-1">HTML 中常见的标签元素及其分类 <a class="header-anchor" href="#html-中常见的标签元素及其分类" aria-label="Permalink to &quot;HTML 中常见的标签元素及其分类&quot;">​</a></h3><p>HTML 标签可以按照功能和用途进行分类，以下是一些常见分类及对应的标签：</p><hr><h4 id="_1-文档结构标签" tabindex="-1">1. <strong>文档结构标签</strong> <a class="header-anchor" href="#_1-文档结构标签" aria-label="Permalink to &quot;1. **文档结构标签**&quot;">​</a></h4><p>用于定义网页的基本结构。</p><ul><li><code>&lt;html&gt;</code>：根标签，表示 HTML 文档的开始和结束。</li><li><code>&lt;head&gt;</code>：包含元信息（如标题、样式、脚本等）。</li><li><code>&lt;body&gt;</code>：包含网页的实际内容。</li></ul><hr><h4 id="_2-文本格式化标签" tabindex="-1">2. <strong>文本格式化标签</strong> <a class="header-anchor" href="#_2-文本格式化标签" aria-label="Permalink to &quot;2. **文本格式化标签**&quot;">​</a></h4><p>用于定义文本的显示方式。</p><ul><li><code>&lt;h1&gt;</code> 至 <code>&lt;h6&gt;</code>：标题标签，表示不同级别的标题。</li><li><code>&lt;p&gt;</code>：段落标签。</li><li><code>&lt;br&gt;</code>：换行标签。</li><li><code>&lt;strong&gt;</code> 或 <code>&lt;b&gt;</code>：加粗文本。</li><li><code>&lt;em&gt;</code> 或 <code>&lt;i&gt;</code>：斜体文本，强调语气。</li><li><code>&lt;u&gt;</code>：下划线文本。</li><li><code>&lt;s&gt;</code>：删除线文本。</li></ul><hr><h4 id="_3-列表标签" tabindex="-1">3. <strong>列表标签</strong> <a class="header-anchor" href="#_3-列表标签" aria-label="Permalink to &quot;3. **列表标签**&quot;">​</a></h4><p>用于创建有序或无序列表。</p><ul><li><code>&lt;ul&gt;</code>：无序列表。</li><li><code>&lt;ol&gt;</code>：有序列表。</li><li><code>&lt;li&gt;</code>：列表项。</li><li><code>&lt;dl&gt;</code>：定义列表。</li><li><code>&lt;dt&gt;</code>：定义术语。</li><li><code>&lt;dd&gt;</code>：描述术语。</li></ul><hr><h4 id="_4-链接与导航标签" tabindex="-1">4. <strong>链接与导航标签</strong> <a class="header-anchor" href="#_4-链接与导航标签" aria-label="Permalink to &quot;4. **链接与导航标签**&quot;">​</a></h4><p>用于实现页面间的跳转。</p><ul><li><code>&lt;a&gt;</code>：超链接标签，通过 <code>href</code> 属性指定目标地址。</li><li><code>&lt;nav&gt;</code>：定义导航链接部分。</li></ul><hr><h4 id="_5-图像与多媒体标签" tabindex="-1">5. <strong>图像与多媒体标签</strong> <a class="header-anchor" href="#_5-图像与多媒体标签" aria-label="Permalink to &quot;5. **图像与多媒体标签**&quot;">​</a></h4><p>用于插入图片、音频、视频等内容。</p><ul><li><code>&lt;img&gt;</code>：插入图像，需指定 <code>src</code> 属性。</li><li><code>&lt;audio&gt;</code>：嵌入音频。</li><li><code>&lt;video&gt;</code>：嵌入视频。</li><li><code>&lt;source&gt;</code>：为多媒体提供多个资源选项。</li></ul><hr><h4 id="_6-表格标签" tabindex="-1">6. <strong>表格标签</strong> <a class="header-anchor" href="#_6-表格标签" aria-label="Permalink to &quot;6. **表格标签**&quot;">​</a></h4><p>用于创建和组织数据表格。</p><ul><li><code>&lt;table&gt;</code>：定义表格。</li><li><code>&lt;tr&gt;</code>：定义表格中的行。</li><li><code>&lt;td&gt;</code>：定义表格中的单元格。</li><li><code>&lt;th&gt;</code>：定义表格中的表头单元格。</li><li><code>&lt;thead&gt;</code>、<code>&lt;tbody&gt;</code>、<code>&lt;tfoot&gt;</code>：分别定义表格的头部、主体和底部。</li></ul><hr><h4 id="_7-表单与输入标签" tabindex="-1">7. <strong>表单与输入标签</strong> <a class="header-anchor" href="#_7-表单与输入标签" aria-label="Permalink to &quot;7. **表单与输入标签**&quot;">​</a></h4><p>用于收集用户输入。</p><ul><li><code>&lt;form&gt;</code>：定义表单容器。</li><li><code>&lt;input&gt;</code>：定义输入控件（如文本框、按钮、复选框等）。</li><li><code>&lt;button&gt;</code>：定义按钮。</li><li><code>&lt;textarea&gt;</code>：多行文本输入框。</li><li><code>&lt;select&gt;</code> 和 <code>&lt;option&gt;</code>：下拉菜单。</li><li><code>&lt;label&gt;</code>：为表单控件提供说明。</li></ul><hr><h4 id="_8-语义化标签" tabindex="-1">8. <strong>语义化标签</strong> <a class="header-anchor" href="#_8-语义化标签" aria-label="Permalink to &quot;8. **语义化标签**&quot;">​</a></h4><p>用于增强网页的可读性和语义性。</p><ul><li><code>&lt;header&gt;</code>：定义页面或章节的头部。</li><li><code>&lt;footer&gt;</code>：定义页面或章节的底部。</li><li><code>&lt;article&gt;</code>：定义独立的内容块。</li><li><code>&lt;section&gt;</code>：定义文档中的节。</li><li><code>&lt;aside&gt;</code>：定义侧边栏内容。</li><li><code>&lt;main&gt;</code>：定义文档的主要内容。</li><li><code>&lt;nav&gt;</code>：定义导航链接部分。</li></ul><hr><h4 id="_9-嵌入内容标签" tabindex="-1">9. <strong>嵌入内容标签</strong> <a class="header-anchor" href="#_9-嵌入内容标签" aria-label="Permalink to &quot;9. **嵌入内容标签**&quot;">​</a></h4><p>用于嵌入外部内容。</p><ul><li><code>&lt;iframe&gt;</code>：嵌入另一个 HTML 页面。</li><li><code>&lt;embed&gt;</code>：嵌入外部应用或交互内容。</li><li><code>&lt;object&gt;</code>：嵌入外部对象（如 Flash）。</li></ul><hr><h4 id="_10-特殊用途标签" tabindex="-1">10. <strong>特殊用途标签</strong> <a class="header-anchor" href="#_10-特殊用途标签" aria-label="Permalink to &quot;10. **特殊用途标签**&quot;">​</a></h4><ul><li><code>&lt;div&gt;</code>：通用容器，用于分组其他 HTML 元素。</li><li><code>&lt;span&gt;</code>：内联容器，用于对文本进行样式化或其他操作。</li><li><code>&lt;canvas&gt;</code>：用于绘制图形（需要 JavaScript 支持）。</li><li><code>&lt;svg&gt;</code>：用于定义矢量图形。</li></ul><hr><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>HTML 标签可以根据其功能分为上述类别，每种标签都有特定的用途，合理使用标签可以使网页结构清晰、语义明确，并为后续的样式设计和交互开发奠定基础。</p>',44)]))}const _=t(i,[["render",a]]);export{u as __pageData,_ as default};
